import type { CurrencyCode } from '@bolsillo/core/money';
import { sql } from 'drizzle-orm';
import { bigint, char, timestamp, uuid } from 'drizzle-orm/pg-core';

/** UUID v7 primary key generated by Postgres 18 (`uuidv7()`) unless the client sends one. */
export const primaryId = () => uuid().primaryKey().default(sql`uuidv7()`);

export const timestamptz = () => timestamp({ withTimezone: true, mode: 'date' });

export const timestamps = {
  createdAt: timestamptz().notNull().defaultNow(),
  updatedAt: timestamptz()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

/** Integer amount in minor units, read as a JS number (always a safe integer). */
export const minor = () => bigint({ mode: 'number' });

export const currency = () => char({ length: 3 }).$type<CurrencyCode>();
